#!/usr/bin/env tsx
// External pi-intercom inspector — list / message live pi sessions from outside a Pi session.
// Reuses nicobailon/pi-intercom's IntercomClient. Run with that repo's tsx:
//   <repo>/node_modules/.bin/tsx intercom-inspect.mjs list
//   <repo>/node_modules/.bin/tsx intercom-inspect.mjs send "<name|id>" "<message>"
//   <repo>/node_modules/.bin/tsx intercom-inspect.mjs broadcast "<message>"   (sends to every other session)
import { IntercomClient } from "/Users/luke/.pi/agent/git/github.com/nicobailon/pi-intercom/broker/client.ts";

const [, , action, arg1, arg2] = process.argv;
const now = Date.now();
const me = {
  name: "claude-code:pi-opt-inspector",
  cwd: "/Users/luke/Projects/personal/my-pi-pi-optimisation",
  model: "claude-opus-4-8",
  pid: process.pid,
  startedAt: now,
  lastActivity: now,
  status: "inspecting",
};

const c = new IntercomClient();
const fail = (m, e) => { console.error(m, e?.message ?? e); process.exit(1); };

try {
  await c.connect(me);
} catch (e) { fail("connect failed:", e); }

try {
  const sessions = await c.listSessions();
  const others = sessions.filter((s) => s.id !== c.sessionId);
  if (action === "list" || !action) {
    console.log(`connected as ${c.sessionId}; ${sessions.length} session(s), ${others.length} other(s):`);
    for (const s of sessions) {
      const age = Math.round((Date.now() - (s.lastActivity ?? Date.now())) / 1000);
      console.log(`- ${s.name ?? "(unnamed)"} [${String(s.id).slice(0, 8)}] cwd=${s.cwd ?? "?"} model=${s.model ?? "?"} status=${s.status ?? "?"} idle=${age}s pid=${s.pid ?? "?"}${s.id === c.sessionId ? " (self)" : ""}`);
    }
  } else if (action === "send") {
    const r = await c.send(arg1, { message: arg2 });
    console.log(`sent to ${arg1}:`, JSON.stringify(r));
  } else if (action === "broadcast") {
    for (const s of others) {
      try { await c.send(s.id, { message: arg1 }); console.log(`sent to ${s.name ?? s.id}`); }
      catch (e) { console.log(`failed to ${s.name ?? s.id}: ${e?.message ?? e}`); }
    }
  }
} catch (e) { fail("action failed:", e); }
finally {
  try { await c.disconnect(); } catch {}
  process.exit(0);
}

