import { chmodSync, existsSync, mkdirSync, mkdtempSync, readFileSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import type { MemoryDb, ObservationSearchRow } from "./db.js";
import { buildMemoryStatus, formatMemoryStatus } from "./status.js";
import type { PiMemoryConfig } from "./config.js";
import { buildStableExtractorSystemPrompt, projectDir, renderParentMemoryPromptSnapshot, type ExtensionContext } from "./util.js";

export interface DreamRunResult {
	status: "no-pending" | "completed" | "failed";
	jobId?: string;
	paths: string[];
	error?: string;
}

export interface MemoryPreviewResult {
	status: "empty" | "ready";
	path?: string;
	changes: number;
}

export function formatDreamStatus(config: PiMemoryConfig, slug: string, db: MemoryDb): string {
	const status = buildMemoryStatus(config, slug, db);
	const jobs = status.extractionJobSummary.length
		? status.extractionJobSummary.map((job) => `${job.status} ${job.count}`).join(", ")
		: "none";
	return `${formatMemoryStatus(status)}\nconsolidation jobs: ${jobs}`;
}

export function enqueueDreamConsolidation(db: MemoryDb, slug: string, sessionId: string, reason = "manual-command"): string {
	return db.enqueueExtractionJob({ scope: "project", projectSlug: slug, sourceSessionId: sessionId, reason });
}

export async function runNextDreamConsolidationWithAgent(db: MemoryDb, ctx: ExtensionContext, config: PiMemoryConfig, projectSlug?: string): Promise<DreamRunResult> {
	const job = db.nextPendingExtractionJob(projectSlug);
	if (!job) return { status: "no-pending", paths: [] };
	if (typeof ctx.forkAgent !== "function") return runNextDreamConsolidation(db, projectSlug);
	db.updateExtractionJob(job.id, { status: "running" });
	const slug = job.projectSlug ?? "unnamed";
	const path = join(projectDir(slug), "MEMORY.md");
	try {
		mkdirSync(dirname(path), { recursive: true });
		const observations = db.observationsForProject(slug, 80);
		const current = existsSync(path) ? readFileSync(path, "utf8") : `# Project Memory: ${slug}\n`;
		const result = await ctx.forkAgent({
			prompt: buildDreamMergePrompt({ slug, path, current, observations }),
			allowedTools: ["read", "write", "edit"],
			model: config.models.smart ?? config.models.frontier ?? config.models.medium,
			description: "pi-memory dream consolidation",
			metadata: { intercom: { hidden: true, kind: "pi-memory-dream" } },
			context: "none",
			systemPrompt: buildStableExtractorSystemPrompt(),
			maxTurns: config.write.maxTurns,
			maxOutputTokens: config.write.maxOutputTokens,
		});
		await result.handle.wait();
		db.upsertMemoryFile({ path, scope: "project", projectSlug: slug, type: "project" });
		renderParentMemoryPromptSnapshot(slug, { maxBytes: config.indexMaxBytes, maxLines: config.indexMaxLines });
		db.updateExtractionJob(job.id, { status: "completed", outputPaths: [path] });
		return { status: "completed", jobId: job.id, paths: [path] };
	} catch (error) {
		const message = error instanceof Error ? error.message : String(error);
		db.updateExtractionJob(job.id, { status: "failed", error: message });
		return { status: "failed", jobId: job.id, paths: [], error: message };
	}
}

export function runNextDreamConsolidation(db: MemoryDb, projectSlug?: string): DreamRunResult {
	const job = db.nextPendingExtractionJob(projectSlug);
	if (!job) return { status: "no-pending", paths: [] };
	db.updateExtractionJob(job.id, { status: "running" });
	try {
		const slug = job.projectSlug ?? "unnamed";
		const observations = db.observationsForProject(slug, 50);
		const path = upsertProjectMemoryIndex(slug, observations);
		db.upsertMemoryFile({ path, scope: "project", projectSlug: slug, type: "project" });
		renderParentMemoryPromptSnapshot(slug);
		db.updateExtractionJob(job.id, { status: "completed", outputPaths: [path] });
		return { status: "completed", jobId: job.id, paths: [path] };
	} catch (error) {
		const message = error instanceof Error ? error.message : String(error);
		db.updateExtractionJob(job.id, { status: "failed", error: message });
		return { status: "failed", jobId: job.id, paths: [], error: message };
	}
}

export async function renderMemoryPreviewWithAgent(slug: string, db: MemoryDb, ctx: ExtensionContext, config: PiMemoryConfig): Promise<MemoryPreviewResult> {
	if (typeof ctx.forkAgent !== "function") return renderMemoryPreview(slug, db);
	const observations = db.observationsForProject(slug, 80);
	const canonicalPath = join(projectDir(slug), "MEMORY.md");
	const current = existsSync(canonicalPath) ? readFileSync(canonicalPath, "utf8") : `# Project Memory: ${slug}\n`;
	if (observations.length === 0) return { status: "empty", changes: 0 };
	const root = mkdtempSync(join(tmpdir(), "pi-memory-preview-"));
	chmodSync(root, 0o700);
	const proposedPath = join(root, "proposed-MEMORY.md");
	const diffPath = join(root, "diff.patch");
	writeFileSync(proposedPath, current, "utf8");
	const result = await ctx.forkAgent({
		prompt: buildDreamMergePrompt({ slug, path: proposedPath, current, observations }),
		allowedTools: ["read", "write", "edit"],
		model: config.models.smart ?? config.models.frontier ?? config.models.medium,
		description: "pi-memory dream preview",
		metadata: { intercom: { hidden: true, kind: "pi-memory-preview" } },
		context: "none",
		systemPrompt: buildStableExtractorSystemPrompt(),
		maxTurns: config.write.maxTurns,
		maxOutputTokens: config.write.maxOutputTokens,
	});
	await result.handle.wait();
	const proposed = existsSync(proposedPath) ? readFileSync(proposedPath, "utf8") : current;
	const changes = changedLineCount(current, proposed);
	if (changes === 0) return { status: "empty", changes: 0 };
	writeFileSync(diffPath, renderPreviewPatch(slug, current, proposed), "utf8");
	return { status: "ready", path: diffPath, changes };
}

export function renderMemoryPreview(slug: string, db: MemoryDb): MemoryPreviewResult {
	const observations = db.observationsForProject(slug, 50);
	const preview = buildProjectMemoryPreview(slug, observations);
	if (preview.lines.length === 0) return { status: "empty", changes: 0 };
	const root = mkdtempSync(join(tmpdir(), "pi-memory-preview-"));
	chmodSync(root, 0o700);
	const path = join(root, "diff.patch");
	writeFileSync(path, renderPreviewPatch(slug, preview.existing, preview.proposed), "utf8");
	return { status: "ready", path, changes: preview.lines.length };
}

export function upsertProjectMemoryIndex(slug: string, observations: readonly ObservationSearchRow[]): string {
	const path = join(projectDir(slug), "MEMORY.md");
	mkdirSync(dirname(path), { recursive: true });
	const preview = buildProjectMemoryPreview(slug, observations);
	if (preview.lines.length === 0) {
		if (!existsSync(path)) writeFileSync(path, preview.existing, "utf8");
		return path;
	}
	writeFileSync(path, preview.proposed, "utf8");
	return path;
}

function buildProjectMemoryPreview(slug: string, observations: readonly ObservationSearchRow[]): { existing: string; proposed: string; lines: string[] } {
	const path = join(projectDir(slug), "MEMORY.md");
	const existing = existsSync(path) ? readFileSync(path, "utf8") : `# Project Memory: ${slug}\n`;
	const lines = observations
		.map(observationToMemoryLine)
		.filter((line): line is string => Boolean(line))
		.filter((line, index, all) => all.indexOf(line) === index)
		.filter((line) => !existing.includes(line));
	const prefix = existing.trimEnd();
	const section = existing.includes("## Consolidated notes") ? "" : "\n\n## Consolidated notes";
	return { existing: existing.endsWith("\n") ? existing : `${existing}\n`, proposed: lines.length ? `${prefix}${section}\n${lines.join("\n")}\n` : existing, lines };
}

function changedLineCount(existing: string, proposed: string): number {
	if (existing === proposed) return 0;
	const before = new Set(existing.split(/\r?\n/).map((line) => line.trim()).filter(Boolean));
	return proposed.split(/\r?\n/).map((line) => line.trim()).filter(Boolean).filter((line) => !before.has(line)).length || 1;
}

function renderPreviewPatch(slug: string, existing: string, proposed: string): string {
	return [
		`# pi-memory preview — project/${slug}/MEMORY.md`,
		"# Approve: /dream now    Veto: edit inbox/observations    Defer: do nothing",
		"--- current/project/MEMORY.md",
		"+++ proposed/project/MEMORY.md",
		"@@",
		...existing.split(/\r?\n/).filter(Boolean).map((line) => `-${line}`),
		...proposed.split(/\r?\n/).filter(Boolean).map((line) => `+${line}`),
		"",
	].join("\n");
}

export function buildDreamMergePrompt(input: { slug: string; path: string; current: string; observations: readonly ObservationSearchRow[] }): string {
	const observations = input.observations.length
		? input.observations.map((row) => `- ${row.ts} [${row.kind}] ${normalizeObservationText(row.content)}`).join("\n")
		: "- No durable observations found.";
	return [
		"You are consolidating pi-memory observations into the canonical project MEMORY.md index.",
		"Keep the file compact, deduped, and useful for future sessions. Preserve existing headings. Do not store secrets, raw logs, transient status, or derivable repo facts.",
		"Write the final merged markdown to the exact target path. Prefer improving existing bullets over appending duplicates.",
		`Project slug: ${input.slug}`,
		`Target path: ${input.path}`,
		"",
		"## Current MEMORY.md",
		input.current.trim() || `# Project Memory: ${input.slug}`,
		"",
		"## New durable observations",
		observations,
	].join("\n");
}

function observationToMemoryLine(row: ObservationSearchRow): string | undefined {
	const text = normalizeObservationText(row.content);
	if (!text) return undefined;
	const tag = row.kind === "manual_note" ? "note" : row.kind === "shutdown_journal" ? "session" : "prompt";
	return `- (${tag}) ${text}`;
}

function normalizeObservationText(content: string): string {
	return content
		.replace(/\s+/g, " ")
		.replace(/^-\s*/, "")
		.trim()
		.slice(0, 300);
}

