1	/**
2	 * task-tools parameter schemas — two deliberately separate layers.
3	 *
4	 *   1. Declared wire schema (TypeBox). What `pi.registerTool({ parameters })`
5	 *      serialises into the model-facing `tools[]` JSON Schema. pi requires a
6	 *      TypeBox `TSchema` here and the emitted bytes are cache-critical: they
7	 *      must stay byte-identical within a session (these are deferLoading tools,
8	 *      activated on demand). We deliberately do NOT regenerate them from Effect
9	 *      Schema — Effect's JSONSchema.make emits a different shape and would shift
10	 *      the cached prefix. TypeBox stays the cache-stable *declared* schema; we
11	 *      never coerce by mutating it.
12	 *
13	 *   2. Runtime validation (Effect Schema). The typed decode/validation contract
14	 *      that runs in `execute`. `normalizeTaskDraft` is the tolerant-coercion
15	 *      boundary (unwrap legacy `{task}` wrappers, JSON.parse stringified args,
16	 *      map title→subject / body→description); after coercion the result is
17	 *      decoded *strictly* by Effect Schema, which surfaces typed decode errors
18	 *      (`TaskParamsError`). Coerce tolerantly at the boundary, validate strictly
19	 *      inside.
20	 */
21	import { Type } from "@sinclair/typebox";
22	import { Either, ParseResult, Schema } from "effect";
23	
24	export const taskStatuses = ["pending", "in_progress", "completed"] as const;
25	
26	export type TaskStatus = (typeof taskStatuses)[number];
27	
28	// Accepted by task_update only (CC TaskUpdate parity): `deleted` permanently
29	// removes the record, so it is never a stored TaskStatus.
30	export const taskUpdateStatuses = [...taskStatuses, "deleted"] as const;
31	
32	export type TaskUpdateStatus = (typeof taskUpdateStatuses)[number];
33	
34	export interface PlanningTask {
35		id: string;
36		subject: string;
37		description?: string;
38		activeForm?: string;
39		status: TaskStatus;
40		owner?: string;
41		metadata?: Record<string, unknown>;
42		blockedBy: string[];
43		blocks: string[];
44		createdAt: number;
45		updatedAt: number;
46	}
47	
48	export interface TaskSnapshot {
49		tasks: PlanningTask[];
50	}
51	
52	// ── Declared wire schema (TypeBox, cache-stable) ────────────────────────────
53	// These objects are the model-facing JSON Schema pi puts in `tools[]`. Keep them
54	// byte-stable; do not regenerate from Effect Schema (see file header).
55	
56	const subjectField = Type.Optional(
57		Type.String({ description: "Imperative task title, e.g. 'Fix login redirect'. Required." }),
58	);
59	const descriptionField = Type.Optional(Type.String({ description: "Extra detail or acceptance notes." }));
60	const activeFormField = Type.Optional(
61		Type.String({ description: "Present-continuous label shown while the task is in_progress, e.g. 'Designing auth schema'. Falls back to subject." }),
62	);
63	const blockedByField = Type.Optional(Type.Array(Type.String(), { description: "Task ids that must complete first." }));
64	const ownerField = Type.Optional(Type.String({ description: "Human label or agent runId responsible for the task." }));
65	const metadataField = Type.Optional(
66		Type.Record(Type.String(), Type.Unknown(), { description: "Arbitrary metadata to attach to the task." }),
67	);
68	
69	const TaskDraftObject = Type.Object({
70		subject: Type.String({ description: "Short task title." }),
71		description: descriptionField,
72		activeForm: activeFormField,
73		blockedBy: blockedByField,
74		owner: ownerField,
75		metadata: metadataField,
76	});
77	
78	// Flat top-level params are the documented happy path (CC TodoWrite style: no
79	// wrapper object). The optional `task` field tolerates the legacy
80	// {task:{...}}/{task:"..."} shape so older callers and stringified input still
81	// work. normalizeTaskDraft enforces that a subject is ultimately present.
82	export const TaskCreateParams = Type.Object({
83		subject: subjectField,
84		description: descriptionField,
85		activeForm: activeFormField,
86		blockedBy: blockedByField,
87		owner: ownerField,
88		metadata: metadataField,
89		task: Type.Optional(
90			Type.Union([TaskDraftObject, Type.String()], {
91				description: "Legacy/alternate form: a {subject, description?, ...} object or a plain string. Prefer the flat top-level fields above.",
92			}),
93		),
94	});
95	
96	export const TaskGetParams = Type.Object({
97		task_id: Type.Optional(Type.String({ description: "Task id, e.g. task-1. Pi-compatible spelling." })),
98		taskId: Type.Optional(Type.String({ description: "Task id, e.g. task-1. Claude Code-compatible spelling." })),
99	});
100	
101	export const TaskUpdateParams = Type.Object({
102		task_id: Type.Optional(Type.String({ description: "Task id to update, e.g. 'task-2'. Pi-compatible spelling." })),
103		taskId: Type.Optional(Type.String({ description: "Task id to update, e.g. 'task-2'. Claude Code-compatible spelling." })),
104		status: Type.Optional(
105			Type.Union(
106				taskUpdateStatuses.map((status) => Type.Literal(status)),
107				{ description: "pending|in_progress|completed, or deleted to permanently remove the task." },
108			),
109		),
110		subject: Type.Optional(Type.String({ description: "Replacement task title." })),
111		description: Type.Optional(Type.String({ description: "Replacement task description." })),
112		activeForm: activeFormField,
113		owner: Type.Optional(Type.String({ description: "Human label or agent runId responsible for the task." })),
114		metadata: Type.Optional(
115			Type.Record(Type.String(), Type.Unknown(), {
116				description: "Metadata keys to merge into the task. Set a key to null to delete it.",
117			}),
118		),
119		// Dependency edits. Prefer the additive verbs (CC TaskUpdate style); use
120		// blockedBy only to replace the whole list at once.
121		addBlockedBy: Type.Optional(
122			Type.Array(Type.String(), { description: "Task ids to add as blockers (this task waits on them)." }),
123		),
124		removeBlockedBy: Type.Optional(
125			Type.Array(Type.String(), { description: "Blocker task ids to remove from this task." }),
126		),
127		addBlocks: Type.Optional(
128			Type.Array(Type.String(), { description: "Task ids that this task blocks (they wait on this task)." }),
129		),
130		removeBlocks: Type.Optional(
131			Type.Array(Type.String(), { description: "Task ids to stop blocking." }),
132		),
133		blockedBy: Type.Optional(
134			Type.Array(Type.String(), { description: "Replace the entire blocker list. Prefer addBlockedBy/removeBlockedBy for incremental edits." }),
135		),
136	});
137	
