/**
 * task-tools parameter schemas — two deliberately separate layers.
 *
 *   1. Declared wire schema (TypeBox). What `pi.registerTool({ parameters })`
 *      serialises into the model-facing `tools[]` JSON Schema. pi requires a
 *      TypeBox `TSchema` here and the emitted bytes are cache-critical: they
 *      must stay byte-identical within a session (these are deferLoading tools,
 *      activated on demand). We deliberately do NOT regenerate them from Effect
 *      Schema — Effect's JSONSchema.make emits a different shape and would shift
 *      the cached prefix. TypeBox stays the cache-stable *declared* schema; we
 *      never coerce by mutating it.
 *
 *   2. Runtime validation (Effect Schema). The typed decode/validation contract
 *      that runs in `execute`. `normalizeTaskDraft` is the tolerant-coercion
 *      boundary (unwrap legacy `{task}` wrappers, JSON.parse stringified args,
 *      map title→subject / body→description); after coercion the result is
 *      decoded *strictly* by Effect Schema, which surfaces typed decode errors
 *      (`TaskParamsError`). Coerce tolerantly at the boundary, validate strictly
 *      inside.
 */
import { Type } from "@sinclair/typebox";
import { Either, ParseResult, Schema } from "effect";

export const taskStatuses = ["pending", "in_progress", "completed"] as const;

export type TaskStatus = (typeof taskStatuses)[number];

// Accepted by task_update only (CC TaskUpdate parity): `deleted` permanently
// removes the record, so it is never a stored TaskStatus.
export const taskUpdateStatuses = [...taskStatuses, "deleted"] as const;

export type TaskUpdateStatus = (typeof taskUpdateStatuses)[number];

export interface PlanningTask {
	id: string;
	subject: string;
	description?: string;
	activeForm?: string;
	status: TaskStatus;
	owner?: string;
	metadata?: Record<string, unknown>;
	blockedBy: string[];
	blocks: string[];
	createdAt: number;
	updatedAt: number;
}

export interface TaskSnapshot {
	tasks: PlanningTask[];
}

// ── Declared wire schema (TypeBox, cache-stable) ────────────────────────────
// These objects are the model-facing JSON Schema pi puts in `tools[]`. Keep them
// byte-stable; do not regenerate from Effect Schema (see file header).

const subjectField = Type.Optional(
	Type.String({ description: "Imperative task title, e.g. 'Fix login redirect'. Required." }),
);
const descriptionField = Type.Optional(Type.String({ description: "Extra detail or acceptance notes." }));
const activeFormField = Type.Optional(
	Type.String({ description: "Present-continuous label shown while the task is in_progress, e.g. 'Designing auth schema'. Falls back to subject." }),
);
const blockedByField = Type.Optional(Type.Array(Type.String(), { description: "Task ids that must complete first." }));
const ownerField = Type.Optional(Type.String({ description: "Human label or agent runId responsible for the task." }));
const metadataField = Type.Optional(
	Type.Record(Type.String(), Type.Unknown(), { description: "Arbitrary metadata to attach to the task." }),
);

const TaskDraftObject = Type.Object({
	subject: Type.String({ description: "Short task title." }),
	description: descriptionField,
	activeForm: activeFormField,
	blockedBy: blockedByField,
	owner: ownerField,
	metadata: metadataField,
});

// Flat top-level params are the documented happy path (CC TodoWrite style: no
// wrapper object). The optional `task` field tolerates the legacy
// {task:{...}}/{task:"..."} shape so older callers and stringified input still
// work. normalizeTaskDraft enforces that a subject is ultimately present.
export const TaskCreateParams = Type.Object({
	subject: subjectField,
	description: descriptionField,
	activeForm: activeFormField,
	blockedBy: blockedByField,
	owner: ownerField,
	metadata: metadataField,
	task: Type.Optional(
		Type.Union([TaskDraftObject, Type.String()], {
			description: "Legacy/alternate form: a {subject, description?, ...} object or a plain string. Prefer the flat top-level fields above.",
		}),
	),
});

export const TaskGetParams = Type.Object({
	task_id: Type.Optional(Type.String({ description: "Task id, e.g. task-1. Pi-compatible spelling." })),
	taskId: Type.Optional(Type.String({ description: "Task id, e.g. task-1. Claude Code-compatible spelling." })),
});

export const TaskUpdateParams = Type.Object({
	task_id: Type.Optional(Type.String({ description: "Task id to update, e.g. 'task-2'. Pi-compatible spelling." })),
	taskId: Type.Optional(Type.String({ description: "Task id to update, e.g. 'task-2'. Claude Code-compatible spelling." })),
	status: Type.Optional(
		Type.Union(
			taskUpdateStatuses.map((status) => Type.Literal(status)),
			{ description: "pending|in_progress|completed, or deleted to permanently remove the task." },
		),
	),
	subject: Type.Optional(Type.String({ description: "Replacement task title." })),
	description: Type.Optional(Type.String({ description: "Replacement task description." })),
	activeForm: activeFormField,
	owner: Type.Optional(Type.String({ description: "Human label or agent runId responsible for the task." })),
	metadata: Type.Optional(
		Type.Record(Type.String(), Type.Unknown(), {
			description: "Metadata keys to merge into the task. Set a key to null to delete it.",
		}),
	),
	// Dependency edits. Prefer the additive verbs (CC TaskUpdate style); use
	// blockedBy only to replace the whole list at once.
	addBlockedBy: Type.Optional(
		Type.Array(Type.String(), { description: "Task ids to add as blockers (this task waits on them)." }),
	),
	removeBlockedBy: Type.Optional(
		Type.Array(Type.String(), { description: "Blocker task ids to remove from this task." }),
	),
	addBlocks: Type.Optional(
		Type.Array(Type.String(), { description: "Task ids that this task blocks (they wait on this task)." }),
	),
	removeBlocks: Type.Optional(
		Type.Array(Type.String(), { description: "Task ids to stop blocking." }),
	),
	blockedBy: Type.Optional(
		Type.Array(Type.String(), { description: "Replace the entire blocker list. Prefer addBlockedBy/removeBlockedBy for incremental edits." }),
	),
});

export const TaskListParams = Type.Object({
	status: Type.Optional(Type.Union(taskStatuses.map((status) => Type.Literal(status)))),
	includeCompleted: Type.Optional(Type.Boolean({ description: "Include completed tasks. Default false." })),
});

// ── Runtime validation (Effect Schema, typed decode errors) ─────────────────
// The validation contract that replaces TypeBox's role as the runtime check.
// Decoding strips excess properties (tolerant), enforces field types strictly,
// and yields a typed `TaskParamsError` carrying a readable failure tree.

const TaskStatusSchema = Schema.Literal(...taskStatuses);
const TaskUpdateStatusSchema = Schema.Literal(...taskUpdateStatuses);
const StringArray = Schema.mutable(Schema.Array(Schema.String));
const NonEmptyString = Schema.String.pipe(Schema.minLength(1));
const MetadataRecord = Schema.mutable(Schema.Record({ key: Schema.String, value: Schema.Unknown }));

export const TaskDraftSchema = Schema.Struct({
	subject: NonEmptyString,
	description: Schema.optional(Schema.String),
	activeForm: Schema.optional(Schema.String),
	blockedBy: Schema.optional(StringArray),
	owner: Schema.optional(Schema.String),
	metadata: Schema.optional(MetadataRecord),
});

export const TaskGetSchema = Schema.Struct({
	task_id: NonEmptyString,
});

const LooseTaskIdSchema = Schema.Struct({
	task_id: Schema.optional(Schema.String),
	taskId: Schema.optional(Schema.String),
});

export const TaskUpdateSchema = Schema.Struct({
	task_id: NonEmptyString,
	status: Schema.optional(TaskUpdateStatusSchema),
	subject: Schema.optional(Schema.String),
	description: Schema.optional(Schema.String),
	activeForm: Schema.optional(Schema.String),
	owner: Schema.optional(Schema.String),
	metadata: Schema.optional(MetadataRecord),
	addBlockedBy: Schema.optional(StringArray),
	removeBlockedBy: Schema.optional(StringArray),
	addBlocks: Schema.optional(StringArray),
	removeBlocks: Schema.optional(StringArray),
	blockedBy: Schema.optional(StringArray),
});

export const TaskListSchema = Schema.Struct({
	status: Schema.optional(TaskStatusSchema),
	includeCompleted: Schema.optional(Schema.Boolean),
});

export type TaskDraft = Schema.Schema.Type<typeof TaskDraftSchema>;
export type TaskGetInput = Schema.Schema.Type<typeof TaskGetSchema>;
export type TaskUpdateInput = Schema.Schema.Type<typeof TaskUpdateSchema>;
export type TaskListInput = Schema.Schema.Type<typeof TaskListSchema>;

/** Typed decode failure: a tool-input shape that Effect Schema rejected. */
export class TaskParamsError extends Error {
	readonly _tag = "TaskParamsError";
	constructor(message: string) {
		super(message);
		this.name = "TaskParamsError";
	}
}

/** Decode `input` against `schema`, throwing a typed `TaskParamsError` on failure. */
function decode<A, I>(schema: Schema.Schema<A, I>, input: unknown, what: string): A {
	const result = Schema.decodeUnknownEither(schema)(input);
	if (Either.isLeft(result)) {
		throw new TaskParamsError(`Invalid ${what}: ${ParseResult.TreeFormatter.formatErrorSync(result.left)}`);
	}
	return result.right;
}

export const decodeTaskGet = (input: unknown): TaskGetInput => decode(TaskGetSchema, normalizeTaskId(input, "task_get"), "task_get params");
export const decodeTaskUpdate = (input: unknown): TaskUpdateInput => decode(TaskUpdateSchema, normalizeTaskId(input, "task_update"), "task_update params");
export const decodeTaskListOptions = (input: unknown): TaskListInput => decode(TaskListSchema, input, "task_list params");

function normalizeTaskId(input: unknown, toolName: string): Record<string, unknown> {
	const loose = decode(LooseTaskIdSchema, input, `${toolName} params`);
	const taskId = loose.task_id ?? loose.taskId;
	if (!taskId?.trim()) throw new TaskParamsError(`${toolName} requires task_id (Pi) or taskId (Claude Code).`);
	return { ...(input as Record<string, unknown>), task_id: taskId.trim() };
}

/**
 * Coerce loose task_create params into a validated `TaskDraft`. Accepts the flat
 * top-level shape ({subject, description, ...}), a legacy {task:{...}} wrapper, a
 * stringified-JSON object, or a plain string (first line -> subject, rest ->
 * description). Maps `title`->`subject` and `body`->`description`. The coerced
 * result is then strictly validated by Effect Schema, surfacing a typed
 * `TaskParamsError` when no valid subject can be derived.
 */
export function normalizeTaskDraft(params: unknown): TaskDraft {
	// Unwrap the legacy/alternate `task` field when the flat subject is absent.
	if (params && typeof params === "object" && !Array.isArray(params)) {
		const p = params as Record<string, unknown>;
		const hasFlat = typeof p.subject === "string" || typeof p.title === "string";
		if (!hasFlat && p.task !== undefined) return coerceDraft(p.task);
	}
	return coerceDraft(params);
}

function coerceDraft(input: unknown): TaskDraft {
	let value: unknown = input;
	if (typeof value === "string") {
		const trimmed = value.trim();
		const parsed = trimmed.startsWith("{") ? tryParseJsonObject(trimmed) : undefined;
		if (parsed) {
			value = parsed;
		} else {
			const newline = trimmed.indexOf("\n");
			const subject = (newline === -1 ? trimmed : trimmed.slice(0, newline)).trim();
			const description = newline === -1 ? undefined : trimmed.slice(newline + 1).trim() || undefined;
			return decode(TaskDraftSchema, { subject, description }, "task_create params");
		}
	}
	if (!value || typeof value !== "object") {
		throw new TaskParamsError("task_create requires a task object {subject, description?} or a string.");
	}
	const obj = value as Record<string, unknown>;
	// title -> subject, body -> description alias mapping before strict validation.
	const subject =
		typeof obj.subject === "string" && obj.subject.trim()
			? obj.subject.trim()
			: typeof obj.title === "string" && obj.title.trim()
				? obj.title.trim()
				: "";
	const description =
		typeof obj.description === "string" ? obj.description.trim() || undefined
			: typeof obj.body === "string" ? obj.body.trim() || undefined
				: undefined;
	return decode(
		TaskDraftSchema,
		{
			subject,
			description,
			activeForm: typeof obj.activeForm === "string" ? obj.activeForm.trim() || undefined : undefined,
			// Tolerant: drop a non-array blockedBy / non-string owner / non-object
			// metadata here; strict decode below still validates whatever survives.
			blockedBy: Array.isArray(obj.blockedBy) ? obj.blockedBy : undefined,
			owner: typeof obj.owner === "string" ? obj.owner : undefined,
			metadata:
				obj.metadata && typeof obj.metadata === "object" && !Array.isArray(obj.metadata)
					? (obj.metadata as Record<string, unknown>)
					: undefined,
		},
		"task_create params",
	);
}

function tryParseJsonObject(text: string): Record<string, unknown> | undefined {
	try {
		const parsed = JSON.parse(text);
		return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : undefined;
	} catch {
		return undefined;
	}
}

