#!/usr/bin/env node
// Deterministic Pi-session metrics for the pi-optimisation gap analysis.
// Measures REAL interactive sessions (Projects cwd; excludes pi-suite/tmp/var-folders
// test fixtures) — newest-first, substantive only. No LLM inference: every number
// is computed from the session jsonl.
//
// Pi jsonl schema (verified 2026-06-09):
//   line.type: "session"|"model_change"|"thinking_level_change"|"message"|...
//   message.role: "user"|"assistant"|"toolResult"
//   assistant content blocks: {type:"thinking"|"text"|"toolCall", name, arguments}
//   assistant usage: {input, output, cacheRead, cacheWrite, totalTokens, cost:{total}}
//
// Usage: node measure-pi-sessions.mjs [targetSubstantive=40] [maxScan=800]

import { execSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { basename, join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const TARGET = Number(process.argv[2] || 40);
const MAX_SCAN = Number(process.argv[3] || 800);
const SESS = join(homedir(), ".pi/agent/sessions");
const OUT = join(dirname(fileURLToPath(import.meta.url)), "..", "findings", "pi-session-metrics.json");

const all = execSync(`find ${SESS} -name '*.jsonl' -type f`, { maxBuffer: 1 << 29 })
	.toString().split("\n").filter(Boolean)
	.filter((p) => /\/--Users-luke-Projects/.test(p) && !/pi-suite|-tmp-|var-folders/.test(p));
// filenames start with ISO timestamp → lexical sort = chronological; reverse = newest first
all.sort((a, b) => basename(b).localeCompare(basename(a)));

function analyze(file) {
	let cwd = null, model = null;
	let asstTurns = 0, asstWithTool = 0, parallelTurns = 0, toolCalls = 0;
	let reads = 0, readsNoLimit = 0, bashCalls = 0, cdBash = 0;
	const toolDist = {};
	let cR = 0, cW = 0, out = 0, total = 0, cost = 0;
	const lines = readFileSync(file, "utf8").split("\n");
	for (const ln of lines) {
		if (!ln) continue;
		let o; try { o = JSON.parse(ln); } catch { continue; }
		if (o.type === "session") cwd = o.cwd ?? cwd;
		if (o.type === "model_change") model = o.modelId ?? model;
		if (o.type !== "message") continue;
		const m = o.message; if (!m) continue;
		if (m.role !== "assistant") continue;
		asstTurns++;
		const u = m.usage;
		if (u) { cR += u.cacheRead || 0; cW += u.cacheWrite || 0; out += u.output || 0; total += u.totalTokens || 0; cost += u.cost?.total || 0; }
		const calls = (m.content || []).filter((c) => c.type === "toolCall");
		if (calls.length >= 1) asstWithTool++;
		if (calls.length >= 2) parallelTurns++;
		toolCalls += calls.length;
		for (const c of calls) {
			const n = c.name || "?";
			toolDist[n] = (toolDist[n] || 0) + 1;
			const a = c.arguments || {};
			if (n === "read") { reads++; if (a.offset == null && a.limit == null) readsNoLimit++; }
			if (n === "bash" || n === "shell") {
				bashCalls++;
				const cmd = String(a.command ?? a.cmd ?? "");
				if (/(^|[;&|]\s*|\s)cd\s+\S/.test(cmd)) cdBash++;
			}
		}
	}
	return { file, cwd, model, asstTurns, asstWithTool, parallelTurns, toolCalls, reads, readsNoLimit, bashCalls, cdBash, toolDist, cR, cW, out, total, cost };
}

const picked = [];
let scanned = 0;
for (const f of all) {
	if (picked.length >= TARGET || scanned >= MAX_SCAN) break;
	scanned++;
	let r; try { r = analyze(f); } catch { continue; }
	if (r.asstWithTool >= 5) picked.push(r); // substantive: real tool-using work
}

const sum = (k) => picked.reduce((s, r) => s + r[k], 0);
const agg = {
	generatedFrom: { realSessionsTotal: all.length, scanned, substantiveSampled: picked.length, target: TARGET },
	parallelToolCallRate: +(sum("parallelTurns") / Math.max(1, sum("asstWithTool"))).toFixed(4),
	fullFileReadRate: +(sum("readsNoLimit") / Math.max(1, sum("reads"))).toFixed(4),
	avgToolsPerToolTurn: +(sum("toolCalls") / Math.max(1, sum("asstWithTool"))).toFixed(3),
	cdPerSession: +(sum("cdBash") / Math.max(1, picked.length)).toFixed(2),
	cdBashRate: +(sum("cdBash") / Math.max(1, sum("bashCalls"))).toFixed(4),
	cacheHitRate: +(sum("cR") / Math.max(1, sum("cR") + sum("cW"))).toFixed(4),
	totals: { reads: sum("reads"), readsNoLimit: sum("readsNoLimit"), toolCalls: sum("toolCalls"), bashCalls: sum("bashCalls"), cdBash: sum("cdBash"), asstTurns: sum("asstTurns"), asstWithTool: sum("asstWithTool"), parallelTurns: sum("parallelTurns"), outputTokens: sum("out"), totalTokens: sum("total"), costUSD: +sum("cost").toFixed(2) },
};
const toolDist = {};
for (const r of picked) for (const [n, c] of Object.entries(r.toolDist)) toolDist[n] = (toolDist[n] || 0) + c;
agg.toolDistribution = Object.fromEntries(Object.entries(toolDist).sort((a, b) => b[1] - a[1]));

writeFileSync(OUT, JSON.stringify({ aggregate: agg, sessions: picked.map((r) => ({ file: basename(r.file), cwd: r.cwd, model: r.model, asstWithTool: r.asstWithTool, parallelTurns: r.parallelTurns, reads: r.reads, readsNoLimit: r.readsNoLimit, cdBash: r.cdBash, cacheHit: +(r.cR / Math.max(1, r.cR + r.cW)).toFixed(3), totalTokens: r.total })) }, null, 2));

console.log(JSON.stringify(agg, null, 2));
console.log(`\nwrote ${OUT}`);

