	.toString().split("\n").filter(Boolean)
	// real interactive sessions only: project slug, not temp/skillopt/suite fixtures
	.filter((p) => /-Users-luke-Projects/.test(p) && !/skillopt|pi-suite|-T-|var-folders|tmp/.test(p));
all.sort((a, b) => basename(b).localeCompare(basename(a)));

