for (const f of all) {
	if (picked.length >= TARGET || scanned >= MAX_SCAN) break;
	scanned++;
	let r; try { r = analyze(f); } catch { continue; }
	if (r.asstWithTool >= 5) picked.push(r);
}

const sum = (k) => picked.reduce((s, r) => s + r[k], 0);
const agg = {
	generatedFrom: { realSessionsTotal: all.length, scanned, substantiveSampled: picked.length, target: TARGET },
	parallelToolCallRate: +(sum("parallelTurns") / Math.max(1, sum("asstWithTool"))).toFixed(4),
	fullFileReadRate: +(sum("readsNoLimit") / Math.max(1, sum("reads"))).toFixed(4),
	avgToolsPerToolTurn: +(sum("toolCalls") / Math.max(1, sum("asstWithTool"))).toFixed(3),
	cdPerSession: +(sum("cdBash") / Math.max(1, picked.length)).toFixed(2),
	cdBashRate: +(sum("cdBash") / Math.max(1, sum("bashCalls"))).toFixed(4),
	cacheHitRate: +(sum("cR") / Math.max(1, sum("cR") + sum("cW"))).toFixed(4),
	totals: { reads: sum("reads"), readsNoLimit: sum("readsNoLimit"), toolCalls: sum("toolCalls"), bashCalls: sum("bashCalls"), cdBash: sum("cdBash"), asstWithTool: sum("asstWithTool"), parallelTurns: sum("parallelTurns"), outputTokens: sum("out") },
};
const toolDist = {};
for (const r of picked) for (const [n, c] of Object.entries(r.toolDist)) toolDist[n] = (toolDist[n] || 0) + c;
agg.toolDistribution = Object.fromEntries(Object.entries(toolDist).sort((a, b) => b[1] - a[1]));

