#!/usr/bin/env node
// Deterministic Codex CLI session metrics — the 3rd leg of the Pi↔CC↔Codex
// comparison. Codex's tool model differs (shell-centric exec_command with a
// first-class workdir + max_output_tokens param), so we measure the metrics that
// actually map + the workdir/output-cap design that explains its low cd-waste.
//
// Codex rollout schema (verified 2026-06-09):
//   line.type: "session_meta"|"turn_context"|"response_item"|"event_msg"
//   response_item.payload.type: "function_call"|"function_call_output"|"message"|
//                               "reasoning"|"tool_search_call"|...
//   function_call: {name:"exec_command"|"apply_patch"|..., arguments:<JSON string>}
//     exec_command args: {cmd, workdir, yield_time_ms, max_output_tokens}
//   event_msg token_count payload carries cumulative {total_tokens, model_context_window}
//
// Usage: node measure-codex-sessions.mjs [targetSubstantive=40] [maxScan=400]

import { execSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { basename, join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const TARGET = Number(process.argv[2] || 40);
const MAX_SCAN = Number(process.argv[3] || 400);
const ROOT = join(homedir(), ".codex/sessions");
const OUT = join(dirname(fileURLToPath(import.meta.url)), "..", "findings", "codex-session-metrics.json");

const all = execSync(`find ${ROOT} -name 'rollout-*.jsonl' -type f`, { maxBuffer: 1 << 29 })
	.toString().split("\n").filter(Boolean);
all.sort((a, b) => basename(b).localeCompare(basename(a))); // rollout-<ISO>… → newest first

function parseArgs(a) { try { return typeof a === "string" ? JSON.parse(a) : (a || {}); } catch { return {}; } }

function analyze(file) {
	let cwd = null;
	let funcCalls = 0, exec = 0, execWorkdir = 0, execCd = 0, execOutCap = 0, applyPatch = 0, toolSearch = 0;
	const toolDist = {};
	let lastTotalTokens = 0, ctxWindow = 0;
