		if (o.type === "turn_context") cwd = o.payload?.cwd ?? cwd;
		if (o.type === "event_msg" && /token/i.test(o.payload?.type || "")) {
			const u = o.payload?.info ?? o.payload;
			const tt = u?.total_token_usage?.total_tokens ?? u?.total_tokens ?? o.payload?.total_tokens;
			if (typeof tt === "number") lastTotalTokens = tt;
			const cw = o.payload?.model_context_window ?? u?.model_context_window;
			if (typeof cw === "number") ctxWindow = cw;
		}
		if (o.type !== "response_item") continue;
		const p = o.payload;
		if (!p) continue;
		if (p.type === "tool_search_call") toolSearch++;
		if (p.type !== "function_call") continue;
		funcCalls++;
		const n = p.name || "?";
		toolDist[n] = (toolDist[n] || 0) + 1;
		const a = parseArgs(p.arguments);
		if (n === "exec_command" || n === "shell" || n === "local_shell") {
			exec++;
			if (a.workdir != null && String(a.workdir).trim()) execWorkdir++;
			if (a.max_output_tokens != null) execOutCap++;
