		modeSuffix || (timeout ? theme.fg("muted", ` (timeout ${timeout}s)`) : theme.fg("muted", " (no timeout)"));

	const prompt = `${theme.fg("toolTitle", theme.bold(label))} `;

	if (command === null) return prompt + invalidArgText(theme) + timeoutSuffix;
